// Evidence explains where a piece of information came from, in terms a
// developer can verify by opening the referenced file.
//
// Every automatically detected technology, capability and relationship carries
// at least one Evidence. This is the mechanism that keeps CodeScape honest:
// nothing detected is displayed without a way to check it.
type Evidence struct {
	// FilePath is relative to the repository root, e.g. "package.json".
	FilePath string `json:"filePath"`
	// Line is 1-based; 0 means "not line-specific".
	Line int `json:"line,omitempty"`
	// Snippet is a short excerpt, truncated and stripped of secrets.
	Snippet string `json:"snippet,omitempty"`
	// Detail is the human-readable explanation, e.g.
	// `Detected React from package.json dependency "react"`.
	Detail string `json:"detail"`
}

// Confidence expresses how strongly a detection is believed, from 0 to 1.
//
// The bands are deliberately coarse — a parser reading an exact dependency
// name is Certain; a directory-name heuristic is Low.
type Confidence float64

const (
	ConfidenceCertain Confidence = 1.0
	ConfidenceHigh    Confidence = 0.85
	ConfidenceMedium  Confidence = 0.6
	ConfidenceLow     Confidence = 0.35
)

// Relationship is an edge in the knowledge graph.
//
// The evidence fields are not optional metadata — they are what makes an edge
// reviewable. An unconfirmed edge from ANALYSIS is a suggestion; the same edge
// with IsConfirmed=true is a decision the user has made.
type Relationship struct {
	ID              uuid.UUID        `json:"id"`
	SourceEntityID  uuid.UUID        `json:"sourceEntityId"`
	TargetEntityID  uuid.UUID        `json:"targetEntityId"`
	Type            RelationshipType `json:"relationshipType"`
	Source          Source           `json:"source"`
	Evidence        []Evidence       `json:"evidence"`
	Confidence      Confidence       `json:"confidence"`
	DetectionMethod DetectionMethod  `json:"detectionMethod"`
	IsConfirmed     bool             `json:"isConfirmed"`
	// RejectedAt distinguishes "not yet reviewed" (nil, IsConfirmed=false)
	// from "reviewed and rejected" (non-nil). Rejected edges are retained so
	// the same suggestion is not raised again on the next scan.
	RejectedAt *time.Time `json:"rejectedAt,omitempty"`
	Note       string     `json:"note,omitempty"`
	CreatedAt  time.Time  `json:"createdAt"`
	UpdatedAt  time.Time  `json:"updatedAt"`
}

// Status reports the review state of the edge.
func (r Relationship) Status() string {
	switch {
	case r.RejectedAt != nil:
		return "REJECTED"
	case r.IsConfirmed:
		return "CONFIRMED"
	default:
		return "DETECTED"
	}
}

// Parser turns one file into evidence-backed findings.
//
// Parsers are intentionally independent and stateless: each one looks at a
// single file and reports what it can prove. Cross-file reasoning happens
// later, during normalization, where the full finding set is available.
type Parser interface {
	// Name identifies the parser in logs and warnings.
	Name() string
	// Matches reports whether this parser handles the file.
	Matches(f File) bool
	// Parse extracts findings. It must not panic on malformed input; a file
	// that cannot be understood yields no findings, not an error.
	Parse(f File, content []byte) []domain.ScanFinding
}

// defaultParsers is the ordered parser registry.
func defaultParsers() []Parser {
	return []Parser{
		&codescapeMetadataParser{},
		&packageJSONParser{},
		&lockfileParser{},
		&workspaceParser{},
		&goModParser{},
		&pythonParser{},
		&rustParser{},
		&dartParser{},
		&javaParser{},
		&dockerComposeParser{},
		&dockerfileParser{},
		&openAPIParser{},
		&protoParser{},
		&ciWorkflowParser{},
		&readmeParser{},
		&sqlParser{},
	}
}

order := make([]key, 0, len(in))
merged := make(map[key]domain.ScanFinding, len(in))

for _, f := range in {
	kk := key{f.Kind, f.Key}
	existing, ok := merged[kk]
	if !ok {
		merged[kk] = f
		order = append(order, kk)
		continue
	}
	existing.Evidence = append(existing.Evidence, f.Evidence...)
	if f.Confidence > existing.Confidence {
		existing.Confidence = f.Confidence
		existing.DetectionMethod = f.DetectionMethod
		if f.Value != "" {
			existing.Value = f.Value
		}
	} else if existing.Value == "" {
		existing.Value = f.Value
	}
	if existing.Category == "" {
		existing.Category = f.Category
	}
	merged[kk] = existing
}

out := make([]domain.ScanFinding, 0, len(order))
for _, kk := range order {
	f := merged[kk]
	// Cap evidence per finding: five examples prove the point, and an
	// unbounded list would bloat both storage and the UI.
	if len(f.Evidence) > 5 {
		f.Evidence = f.Evidence[:5]
	}
	out = append(out, f)
}

	if !filepath.IsAbs(trimmed) {
		return "", fmt.Errorf("repository path must be absolute")
	}

	// filepath.Clean collapses "..", but cleaning alone is not sufficient
	// protection — EvalSymlinks below is what makes the check real.
	cleaned := filepath.Clean(trimmed)

	resolved, err := filepath.EvalSymlinks(cleaned)
	if err != nil {
		if os.IsNotExist(err) {
			return "", fmt.Errorf("repository path does not exist")
		}
		return "", fmt.Errorf("repository path is not readable: %w", err)
	}

	info, err := os.Stat(resolved)
	if err != nil {
		return "", fmt.Errorf("repository path is not readable: %w", err)
	}
	if !info.IsDir() {
		return "", ErrNotDirectory
	}

	for _, root := range g.roots {
		if within(root, resolved) {
			return resolved, nil
		}
	}
	return "", ErrOutsideAllowedRoots
}

const attempts = registrations.map(async (registration) => {
  if (registration.status === 'DISABLED') {
    result.disabled.push(registration);
    return;
  }

  // Checked before anything is fetched: once the module is requested the code
  // has already run, so a later check would be too late to matter.
  if (!isOriginAllowed(registration.remoteEntry, allowedOrigins)) {
    result.failed.push({
      registration,
      reason: 'forbidden-origin',
      message:
        `${registration.name} is served from an origin this host is not ` +
        `configured to load code from, so it was not evaluated.`,
      detail:
        `Remote entry: ${registration.remoteEntry}. Allowed origins: ` +
        `${allowedOrigins.join(', ') || 'none configured'}.`,
    });
    return;
  }

  if (!isHostVersionCompatible(hostVersion, registration.compatibleHostVersions)) {
    result.failed.push({
      registration,
      reason: 'incompatible',
      message:
        `${registration.name} supports host version ` +
        `${registration.compatibleHostVersions.join(', ') || 'unspecified'}, ` +
        `but this host is ${hostVersion}.`,
    });
    return;
  }

