/**
 * Where the camera should sit to inspect a planet.
 *
 * The distance scales with the planet's radius so a large hub does not fill
 * the frame and a small one is not a dot, and is floored at the OrbitControls
 * minimum — a goal inside that limit would have the controls fighting the rig
 * forever, which reads on screen as a camera that will not settle.
 */
export function cameraGoalFor(placed: PlacedNode): CameraGoal {
  const [x, y, z] = placed.position;
  const distance = Math.max(MIN_DISTANCE + 2, placed.radius * 6 + 9);

  return {
    // Slightly above and in front, so the planet's label — which sits above it
    // — is not clipped by the top of the viewport.
    position: [x, y + distance * 0.35, z + distance],
    target: [x, y, z],
  };
}
